import { createServer } from 'node:http';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.BOOKS_FILE || join(__dirname, 'books.json');
const PORT = Number(process.env.PORT || 3000);

// ---- data layer ----------------------------------------------------------

/**
 * @typedef {Object} Book
 * @property {string} id
 * @property {string} title
 * @property {string} author
 * @property {string} notes
 * @property {boolean} finished
 * @property {string} createdAt
 */

/** @returns {Promise<Book[]>} */
export async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

/** @param {Book[]} books */
export async function saveBooks(books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + '\n', 'utf8');
}

/** @param {Book[]} books @param {string} id */
export function findBook(books, id) {
  return books.find((b) => b.id === id) || null;
}

/** @param {Book[]} books @param {Partial<Book>} input */
export function addBook(books, input) {
  const book = {
    id: randomUUID(),
    title: (input.title || '').trim(),
    author: (input.author || '').trim(),
    notes: (input.notes || '').trim(),
    finished: Boolean(input.finished),
    createdAt: new Date().toISOString(),
  };
  books.push(book);
  return book;
}

/** @param {Book[]} books @param {string} id @param {boolean} finished */
export function setFinished(books, id, finished) {
  const book = findBook(books, id);
  if (!book) return null;
  book.finished = finished;
  return book;
}

// ---- html helpers --------------------------------------------------------

function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} — Book Tracker</title>
<style>
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
         max-width: 680px; margin: 2rem auto; padding: 0 1rem; color: #1b1b1b; }
  h1 { font-size: 1.6rem; margin: 0 0 1.5rem; }
  h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; color: #555; }
  a { color: #2a5db0; }
  .book { padding: 0.75rem 0; border-bottom: 1px solid #e3e3e3; }
  .book:last-child { border-bottom: none; }
  .book .title { font-weight: 600; }
  .book .author { color: #666; }
  .meta { color: #777; font-size: 0.9rem; }
  form { margin: 1rem 0; }
  label { display: block; margin: 0.6rem 0 0.15rem; font-weight: 600; }
  input[type=text], textarea { width: 100%; box-sizing: border-box;
    padding: 0.5rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
  textarea { min-height: 7rem; resize: vertical; }
  button { margin-top: 0.8rem; padding: 0.5rem 1rem; font: inherit;
    border: 1px solid #2a5db0; background: #2a5db0; color: #fff; border-radius: 6px; cursor: pointer; }
  button.secondary { background: transparent; color: #2a5db0; }
  .actions { margin-top: 0.5rem; display: flex; gap: 0.75rem; align-items: center; }
  .empty { color: #999; font-style: italic; }
  .share { color: #2a5db0; word-break: break-all; font-size: 0.9rem; }
  @media (prefers-color-scheme: dark) {
    body { color: #e8e8e8; }
    h2 { color: #aaa; }
    .book { border-color: #333; }
    .book .author, .meta { color: #aaa; }
    .empty { color: #777; }
    input[type=text], textarea { background: #1e1e1e; border-color: #444; color: #e8e8e8; }
    a, button.secondary { color: #7fa8e8; }
    button { border-color: #7fa8e8; background: #7fa8e8; color: #111; }
  }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookLink(book) {
  return `<div class="book">
    <div class="title"><a href="/books/${esc(book.id)}">${esc(book.title)}</a></div>
    <div class="author">by ${esc(book.author)}</div>
    <div class="actions">
      <form method="post" action="/books/${esc(book.id)}/toggle">
        <input type="hidden" name="finished" value="${book.finished ? 'false' : 'true'}">
        <button class="secondary" type="submit">${book.finished ? 'Mark as reading' : 'Mark as finished'}</button>
      </form>
    </div>
  </div>`;
}

// ---- request handlers ----------------------------------------------------

/** @param {Book[]} books */
function homePage(books) {
  const reading = books.filter((b) => !b.finished).reverse();
  const finished = books.filter((b) => b.finished).reverse();
  const body = `
  <h1>Book Tracker</h1>
  <p><a href="/books/new">+ Add a book</a></p>

  <h2>Currently reading</h2>
  ${reading.length ? reading.map(bookLink).join('') : '<p class="empty">Nothing in progress.</p>'}

  <h2>Finished</h2>
  ${finished.length ? finished.map(bookLink).join('') : '<p class="empty">No finished books yet.</p>'}
  `;
  return layout('Home', body);
}

function newBookPage(errors = {}) {
  const body = `
  <h1>Add a book</h1>
  <form method="post" action="/books">
    <label for="title">Title</label>
    <input type="text" id="title" name="title" value="${esc(errors.values?.title || '')}" required>
    ${errors.title ? `<div class="meta" style="color:#b00">${esc(errors.title)}</div>` : ''}

    <label for="author">Author</label>
    <input type="text" id="author" name="author" value="${esc(errors.values?.author || '')}">
    ${errors.author ? `<div class="meta" style="color:#b00">${esc(errors.author)}</div>` : ''}

    <label for="notes">Notes</label>
    <textarea id="notes" name="notes">${esc(errors.values?.notes || '')}</textarea>

    <label><input type="checkbox" name="finished" value="true" ${errors.values?.finished ? 'checked' : ''}> Already finished</label>

    <button type="submit">Save book</button>
    <a href="/">Cancel</a>
  </form>
  `;
  return layout('Add a book', body);
}

/** @param {Book} book @param {string} origin */
function bookPage(book, origin) {
  const shareUrl = `${origin}/books/${book.id}`;
  const body = `
  <h1>${esc(book.title)}</h1>
  <p class="author">by ${esc(book.author)}</p>
  <p class="meta">Status: ${book.finished ? 'Finished' : 'Currently reading'}</p>

  <h2>Notes</h2>
  ${book.notes ? `<p>${esc(book.notes).replace(/\n/g, '<br>')}</p>` : '<p class="empty">No notes yet.</p>'}

  <div class="actions">
    <form method="post" action="/books/${esc(book.id)}/toggle">
      <input type="hidden" name="finished" value="${book.finished ? 'false' : 'true'}">
      <button class="secondary" type="submit">${book.finished ? 'Mark as reading' : 'Mark as finished'}</button>
    </form>
    <a href="/">Back to list</a>
  </div>

  <h2>Share</h2>
  <p class="meta">Send someone this link to view this book:</p>
  <p class="share"><a href="${esc(shareUrl)}">${esc(shareUrl)}</a></p>
  `;
  return layout(book.title, body);
}

function notFoundPage() {
  return layout('Not found', `<h1>Not found</h1><p><a href="/">Home</a></p>`);
}

// ---- form parsing --------------------------------------------------------

/** @param {string} body */
function parseForm(body) {
  const params = {};
  for (const pair of body.split('&')) {
    const [k, v] = pair.split('=').map(decodeURIComponent);
    if (k) params[k] = v ?? '';
  }
  return params;
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => (data += chunk));
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

// ---- router --------------------------------------------------------------

/** @param {import('node:http').IncomingMessage} req */
function origin(req) {
  const proto = req.headers['x-forwarded-proto'] || 'http';
  const host = req.headers.host || `localhost:${PORT}`;
  return `${proto}://${host}`;
}

/**
 * @param {import('node:http').IncomingMessage} req
 * @param {import('node:http').ServerResponse} res
 */
async function handler(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || `localhost:${PORT}`}`);
  const path = url.pathname;
  const method = req.method;

  try {
    const books = await loadBooks();

    // Home
    if (path === '/' && method === 'GET') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(homePage(books));
      return;
    }

    // New book form
    if (path === '/books/new' && method === 'GET') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(newBookPage());
      return;
    }

    // Create book
    if (path === '/books' && method === 'POST') {
      const params = parseForm(await readBody(req));
      const title = (params.title || '').trim();
      if (!title) {
        res.writeHead(422, { 'content-type': 'text/html; charset=utf-8' });
        res.end(newBookPage({ title: 'Title is required.', values: params }));
        return;
      }
      const book = addBook(books, {
        title,
        author: params.author || '',
        notes: params.notes || '',
        finished: params.finished === 'true',
      });
      await saveBooks(books);
      res.writeHead(303, { location: `/books/${book.id}` });
      res.end();
      return;
    }

    // Toggle finished
    const toggle = path.match(/^\/books\/([^/]+)\/toggle$/);
    if (toggle && method === 'POST') {
      const params = parseForm(await readBody(req));
      const updated = setFinished(books, toggle[1], params.finished === 'true');
      if (!updated) {
        res.writeHead(404, { 'content-type': 'text/html; charset=utf-8' });
        res.end(notFoundPage());
        return;
      }
      await saveBooks(books);
      res.writeHead(303, { location: '/' });
      res.end();
      return;
    }

    // Book detail
    const detail = path.match(/^\/books\/([^/]+)$/);
    if (detail && method === 'GET') {
      const book = findBook(books, detail[1]);
      if (!book) {
        res.writeHead(404, { 'content-type': 'text/html; charset=utf-8' });
        res.end(notFoundPage());
        return;
      }
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(bookPage(book, origin(req)));
      return;
    }

    res.writeHead(404, { 'content-type': 'text/html; charset=utf-8' });
    res.end(notFoundPage());
  } catch (err) {
    console.error(err);
    res.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
    res.end('Internal error');
  }
}

// ---- bootstrap -----------------------------------------------------------

export function createApp() {
  return createServer(handler);
}

if (import.meta.url === `file://${process.argv[1]}` || fileURLToPath(import.meta.url) === process.argv[1]) {
  const server = createApp();
  server.listen(PORT, () => {
    console.log(`Book tracker running at http://localhost:${PORT}`);
  });
}

