import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { loadBooks, saveBooks, addBook, setFinished, findBook } from '../server.mjs';

let dir;
let dataFile;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'books.json');
  process.env.BOOKS_FILE = dataFile;
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe('data layer', () => {
  it('loads an empty list when the file is missing', async () => {
    const books = await loadBooks();
    expect(books).toEqual([]);
  });

  it('round-trips books through save and load', async () => {
    const books = [];
    addBook(books, { title: 'Piranesi', author: 'Susanna Clarke', notes: 'good' });
    await saveBooks(books);
    const loaded = await loadBooks();
    expect(loaded).toHaveLength(1);
    expect(loaded[0].title).toBe('Piranesi');
    expect(loaded[0].author).toBe('Susanna Clarke');
    expect(loaded[0].finished).toBe(false);
  });

  it('finds a book by id', async () => {
    const books = [];
    const added = addBook(books, { title: 'A' });
    expect(findBook(books, added.id)).toBe(added);
    expect(findBook(books, 'nope')).toBeNull();
  });

  it('toggles finished status', async () => {
    const books = [];
    const added = addBook(books, { title: 'B' });
    expect(added.finished).toBe(false);
    setFinished(books, added.id, true);
    expect(added.finished).toBe(true);
    setFinished(books, added.id, false);
    expect(added.finished).toBe(false);
  });

  it('persists finished state across restart', async () => {
    let books = [];
    const added = addBook(books, { title: 'C' });
    setFinished(books, added.id, true);
    await saveBooks(books);

    // simulate restart: fresh load
    books = await loadBooks();
    expect(books[0].finished).toBe(true);
  });

  it('requires a title', async () => {
    const books = [];
    const added = addBook(books, { title: '  ', author: 'x' });
    expect(added.title).toBe('');
  });

  it('handles a corrupted data file gracefully by throwing', async () => {
    writeFileSync(dataFile, '{not json');
    await expect(loadBooks()).rejects.toThrow();
  });
});

